package com.cleancity;
import jakarta.servlet.annotation.MultipartConfig; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.sql.*; import java.util.*;
@WebServlet("/api/complaints/*") @MultipartConfig(maxFileSize=8*1024*1024) public class ComplaintServlet extends HttpServlet {
 private Integer uid(HttpServletRequest r){HttpSession s=r.getSession(false);return s==null?null:(Integer)s.getAttribute("uid");}
 protected void doPost(HttpServletRequest r,HttpServletResponse res)throws IOException{Integer u=uid(r);if(u==null){Json.error(res,401,"Please login");return;}try{String d=r.getParameter("description"),l=r.getParameter("location");Part p=r.getPart("photo");if(d==null||l==null||d.isBlank()||l.isBlank()){Json.error(res,400,"Description and location are required");return;}try(Connection c=DB.get()){PreparedStatement s=c.prepareStatement("INSERT INTO complaints(user_id,description,location,photo,photo_type) VALUES(?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS);s.setInt(1,u);s.setString(2,d);s.setString(3,l);if(p!=null&&p.getSize()>0){s.setBinaryStream(4,p.getInputStream());s.setString(5,p.getContentType());}else{s.setNull(4,Types.LONGVARBINARY);s.setNull(5,Types.VARCHAR);}s.executeUpdate();try(ResultSet k=s.getGeneratedKeys()){k.next();Json.send(res,Map.of("ok",true,"id",k.getInt(1)));}}}catch(Exception e){e.printStackTrace();Json.error(res,500,"Could not submit complaint");}}
 protected void doGet(HttpServletRequest r,HttpServletResponse res)throws IOException{Integer u=uid(r);if(u==null){Json.error(res,401,"Please login");return;}String path=r.getPathInfo();try(Connection c=DB.get()){if(path!=null&&path.matches("/\\d+/photo")){int id=Integer.parseInt(path.split("/")[1]);PreparedStatement s=c.prepareStatement("SELECT photo,photo_type FROM complaints WHERE id=? AND user_id=?");s.setInt(1,id);s.setInt(2,u);ResultSet x=s.executeQuery();if(!x.next()||x.getBytes(1)==null){res.setStatus(404);return;}res.setContentType(x.getString(2));res.getOutputStream().write(x.getBytes(1));return;}PreparedStatement s=c.prepareStatement("SELECT id,description,location,status,created_at,updated_at FROM complaints WHERE user_id=? ORDER BY created_at DESC");s.setInt(1,u);ResultSet x=s.executeQuery();List<Map<String,Object>> a=new ArrayList<>();while(x.next())a.add(Map.of("id",x.getInt(1),"description",x.getString(2),"location",x.getString(3),"status",x.getString(4),"createdAt",x.getTimestamp(5).toString(),"updatedAt",x.getTimestamp(6).toString()));Json.send(res,a);}catch(Exception e){e.printStackTrace();Json.error(res,500,"Database error");}}
}
